package net.civeira.phylax.feature.observe.observedfingerprintrule.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.ObservedFingerprintRuleEffectOptions;

class EffectVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property effect of observed fingerprint rule ")
  void test_effect_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> EffectVO.tryFrom("_GROUP_AS_"));
    Assertions.assertEquals(ObservedFingerprintRuleEffectOptions.GROUP_AS,
        EffectVO.tryFrom("GROUP_AS").getEffect());
    Assertions.assertThrows(ConstraintException.class, () -> EffectVO.tryFrom(null));
    Assertions.assertEquals(ObservedFingerprintRuleEffectOptions.GROUP_AS,
        EffectVO.from(ObservedFingerprintRuleEffectOptions.GROUP_AS).getEffect());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> EffectVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedFingerprintRuleEffectOptions.GROUP_AS + "]",
        EffectVO.from(ObservedFingerprintRuleEffectOptions.GROUP_AS).toString());
  }
}
